def max_bitonic_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # inc[i] stores the maximum sum of an increasing subsequence ending at index i
    inc = [0] * n
    # dec[i] stores the maximum sum of a decreasing subsequence starting at index i
    dec = [0] * n

    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

        dec[i] = arr[i]
        for k in range(i + 1, n):
            if arr[k] < arr[i]:
                dec[i] = max(dec[i], dec[k] + arr[i])

    max_sum = 0
    for i in range(n):
        # Combine the increasing part ending at i and decreasing part starting at i
        # Subtract arr[i] because it is included in both inc[i] and dec[i]
        current = inc[i] + dec[i] - arr[i]
        if current > max_sum:
            max_sum = current

    return max_sum

